mapper.select:
SELECT ETR_ENTRUST_ADD.SETTLE_SPREED settleSpeed, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, ETR_ENTRUST.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, ETR_ENTRUST.PS ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket,
ETR_ENTRUST.TRADE_PLAT tradePlat,
ETR_ENTRUST.CHL_ID chlId, ETR_ENTRUST_ADD.SEC_ACCT_ID secAcctId,
ETR_ENTRUST_ADD.TERM_TYPE termType,
ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0), NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))- decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) proAvailableCash, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) finshAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,cast(ETR_ENTRUST.ENTRUST_NUM as DECIMAL(30,2))),4) percent, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, days(to_date(ETR_ENTRUST.MDATE,'yyyy-mm-dd')) - days(to_date(current date,'yyyy-mm-dd')) as days, ETR_ENTRUST_ADD.TERM_DAYS repoTerm, ETR_ENTRUST.price price, ETR_ENTRUST_ADD.MATURE_YIELD matureYield, ETR_ENTRUST_ADD.EXER_YIELD exerYield, ETR_ENTRUST.PRICE_MODEL priceMode FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
ETR_DISTRIBUTE.TRADER = #{loginUser} AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustCompleted},#{entrustReceive},#{entrustClose}) AND ETR_DISTRIBUTE.REC_STATUS IN(#{entrustCompleted},#{entrustReceive},#{entrustClose})
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND (FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat(concat('%',#{finprodMarketId,jdbcType=VARCHAR}),'%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat(concat('%',#{finprodMarketId,jdbcType=VARCHAR}),'%'))
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatus1},#{entrustStatus2})
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus}
AND ETR_ENTRUST.ENTRUST_DATE >= to_date(#{beginDate},'yyyy-mm-dd')
AND ETR_ENTRUST.ENTRUST_DATE <= to_date(#{endDate},'yyyy-mm-dd')
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}
AND ETR_ENTRUST_ADD.ASSET_TYPE in ('F01','F07') and ETR_ENTRUST.TRADE_MARKET in ('01','03','04')
and ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST.VDATE >= to_date(#{cstpTradeDate},'yyyy-mm-dd') AND ETR_ENTRUST.MDATE <= to_date(#{cstpTradeDate},'yyyy-mm-dd')
and ETR_ENTRUST_ADD.TERM_DAYS = #{repoTerm}
and ETR_ENTRUST_ADD.SEC_ACCT_ID = #{secAcctId}
ORDER BY ETR_ENTRUST.ENTRUST_DATE DESC

SELECT ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, ETR_ENTRUST.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, ETR_ENTRUST.PS ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0), NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))- decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) proAvailableCash, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) finshAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,cast(ETR_ENTRUST.ENTRUST_NUM as DECIMAL(30,2))),2) percent, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, days(to_date(ETR_ENTRUST.MDATE,'yyyy-mm-dd')) - days(to_date(current date,'yyyy-mm-dd')) as days, ETR_ENTRUST_ADD.TERM_TYPE termType FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
ETR_DISTRIBUTE.TRADER = #{loginUser} AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustAwait}
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND (FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat(concat('%',#{finprodMarketId,jdbcType=VARCHAR}),'%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat(concat('%',#{finprodMarketId,jdbcType=VARCHAR}),'%'))
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_DATE >= to_date(#{beginDate},'yyyy-mm-dd')
AND ETR_ENTRUST.ENTRUST_DATE <= to_date(#{endDate},'yyyy-mm-dd')
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}
ORDER BY ETR_ENTRUST.ENTRUST_DATE DESC
